nginx_config:
daemon off;
master_process on;
worker_processes 2;
pid /tmp/aegisx-bench-uqnjsm_e/nginx.pid;
error_log /tmp/aegisx-bench-uqnjsm_e/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-uqnjsm_e/body;
    proxy_temp_path /tmp/aegisx-bench-uqnjsm_e/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 10.42.1.170:3900; keepalive 256; }
    server {

        listen 10.42.1.79:29131   reuseport;
        location / {
            root /tmp/aegisx-bench-uqnjsm_e/site;
            open_file_cache max=1000 inactive=60s;
            open_file_cache_valid 1s;
        }
    }
}
